   "id": "BUG-025",
   "title": "Location offers get no discount at real New York coordinates, because the city table has New York at longitude +74 instead of -74",
   "status": "open",
   "severity": "minor",
   "layer": "api",
   "area": "carts",
   "affects": [
    "POST /carts/{cartId}",
    "GET /carts/{cartId}"
   ],
